window.ScripturaLexicons.BDAG_PART_0249 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-01\" data-source=\"BDAG\" data-search=\"ξίφος, εος substantivo neutro espada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξίφος, εος</td><td>substantivo neutro</td><td>espada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-02\" data-source=\"BDAG\" data-search=\"ξόανον, ου, τό substantivo neutro imagem cultual de madeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξόανον, ου, τό</td><td>substantivo neutro</td><td>imagem cultual de madeira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-03\" data-source=\"BDAG\" data-search=\"ξύλινος, η, ον adjetivo de madeira; feito de madeira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξύλινος, η, ον</td><td>adjetivo</td><td>de madeira; feito de madeira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-04\" data-source=\"BDAG\" data-search=\"ξύλον, ου, τό substantivo neutro madeira; objeto de madeira; cruz; árvore BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξύλον, ου, τό</td><td>substantivo neutro</td><td>madeira; objeto de madeira; cruz; árvore</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-05\" data-source=\"BDAG\" data-search=\"ξυν- remissão ver συν- BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξυν-</td><td>remissão</td><td>ver συν-</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-06\" data-source=\"BDAG\" data-search=\"ξυράω verbo raspar; barbear; rapar a cabeça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ξυράω</td><td>verbo</td><td>raspar; barbear; rapar a cabeça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-07\" data-source=\"BDAG\" data-search=\"ὁ, ἡ, τό artigo definido o; a; os; as; demonstrativo e determinativo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁ, ἡ, τό</td><td>artigo definido</td><td>o; a; os; as; demonstrativo e determinativo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-08\" data-source=\"BDAG\" data-search=\"ὀβελίσκος, ου, ὁ substantivo masculino diminutivo pequeno espeto; pequena haste BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀβελίσκος, ου, ὁ</td><td>substantivo masculino diminutivo</td><td>pequeno espeto; pequena haste</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-09\" data-source=\"BDAG\" data-search=\"ὀγδοήκοντα numeral cardinal indeclinável oitenta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀγδοήκοντα</td><td>numeral cardinal indeclinável</td><td>oitenta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-10\" data-source=\"BDAG\" data-search=\"ὄγδοος, η, ον numeral ordinal oitavo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄγδοος, η, ον</td><td>numeral ordinal</td><td>oitavo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-11\" data-source=\"BDAG\" data-search=\"ὄγκος, ου, ὁ substantivo masculino volume; peso; impedimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄγκος, ου, ὁ</td><td>substantivo masculino</td><td>volume; peso; impedimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-12\" data-source=\"BDAG\" data-search=\"ὀγκόω verbo passivo inchar; avolumar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀγκόω</td><td>verbo passivo</td><td>inchar; avolumar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-13\" data-source=\"BDAG\" data-search=\"ὅδε, ἥδε, τόδε pronome demonstrativo este; esta; tal e tal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅδε, ἥδε, τόδε</td><td>pronome demonstrativo</td><td>este; esta; tal e tal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-14\" data-source=\"BDAG\" data-search=\"ὁδεύω verbo viajar; seguir caminho; percorrer uma rota BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁδεύω</td><td>verbo</td><td>viajar; seguir caminho; percorrer uma rota</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-15\" data-source=\"BDAG\" data-search=\"ὁδηγέω verbo conduzir; guiar; orientar; instruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁδηγέω</td><td>verbo</td><td>conduzir; guiar; orientar; instruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-16\" data-source=\"BDAG\" data-search=\"ὁδηγός, οῦ, ὁ substantivo masculino guia; condutor; orientador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁδηγός, οῦ, ὁ</td><td>substantivo masculino</td><td>guia; condutor; orientador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-17\" data-source=\"BDAG\" data-search=\"ὀδμή remissão ver ὀσμή BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀδμή</td><td>remissão</td><td>ver ὀσμή</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-18\" data-source=\"BDAG\" data-search=\"ὁδοιπορέω verbo viajar; estar a caminho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁδοιπορέω</td><td>verbo</td><td>viajar; estar a caminho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-19\" data-source=\"BDAG\" data-search=\"ὁδοιπορία, ας, ἡ substantivo feminino caminhada; viagem; jornada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁδοιπορία, ας, ἡ</td><td>substantivo feminino</td><td>caminhada; viagem; jornada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0249-20\" data-source=\"BDAG\" data-search=\"ὁδοποιέω verbo abrir caminho; construir passagem BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁδοποιέω</td><td>verbo</td><td>abrir caminho; construir passagem</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0249-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξίφος, εος</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξίφος</span>, <span class=\"greek\">εος</span> ou <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom. e posteriores), espada ApcPt 15:30.—B. 1392.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξόανον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξόανον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (autores trágicos e outros; inscrições, papiros), imagem cultual de madeira (assim em Eur.; X., An. 5, 3, 12; inscrições, papiros; Aq. Ezk 6:4; Manetho em Jos., C. Ap. 1, 244; 249; Philo, Mos. 1, 298 e outros; Ath. 4, 1; SibOr 3, 723) ApcPt 18:33.—DELG s.v. <span class=\"greek\">ξέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξύλινος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξύλινος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ξύλον</span>; Pind., Hdt. e posteriores), de madeira: <span class=\"greek\">τὰ</span> <span class=\"greek\">εἴδωλα</span> … <span class=\"greek\">τὰ</span> <span class=\"greek\">ξ</span>., as imagens cultuais/os ídolos de madeira (cf. Aesop, Fab. 66 H.=285 P.//61 Ch.//284 H-H. <span class=\"greek\">ἄνθρωπός</span> <span class=\"greek\">τις</span> <span class=\"greek\">ξύλινον</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">θεόν</span>; EpJer 3 <span class=\"greek\">θεοὶ</span> <span class=\"greek\">ξ</span>., 10, 29, 54, 69, 70; Da 5:4 e 23 Theod.; En 99:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:20</a>. <span class=\"greek\">θεοὶ</span> <span class=\"greek\">ξ</span>. AcPl Ha 1, 19. <span class=\"greek\">σκεύη</span>, recipientes ou utensílios de madeira (cf. SIG 962, 41ff; 316; Lev 15:12; Num 31:20; 35:18) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:20</a>.—DELG s.v. <span class=\"greek\">ξύλον</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξύλον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξύλον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom. e posteriores).</p><p class=\"entry-text\">① Madeira enquanto matéria vegetal em forma não manufaturada, madeira (a madeira destinada ao oferecimento de Isaque ligada tipologicamente à cruz de Cristo: Iren. 4, 5, 4 [Harv. II 157, 2]; Orig., C. Cels. 6, 70, 12) Dg 2:2; Ox 1 recto, 8 (ASyn. 171, 5; cf. GTh 77; ver <span class=\"greek\">λίθος</span> 1). <span class=\"greek\">πᾶν</span> <span class=\"greek\">ξ</span>. <span class=\"greek\">θύϊνον</span>, toda espécie de madeira de tuia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:12</a>a. <span class=\"greek\">ξ</span>. <span class=\"greek\">τιμιώτατον</span>, madeira muito preciosa, versículo 12b. Plural: madeira como material de construção (Diod S 5, 21, 5 <span class=\"greek\">κάλαμοι</span> e <span class=\"greek\">ξύλα</span>; PFlor 16, 23; Just., D. 86, 6 <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκοδομήν</span>; Tat. 37, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:12</a>; para fabricação de imagens cultuais <span class=\"greek\">ξύλα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λίθους</span> (Sextus 568; Tat.4, 2), juntamente com outros materiais 2 Cl 1:6; PtK 2 p. 14, 13 (Ath. 15, 1). Como combustível (POxy 1144, 15 <span class=\"greek\">ξύλα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θυσίαν</span>; Gen 22:3, 6; Lev 1:7) MPol 13:1; Hs 4:4.</p><p class=\"entry-text\">② Objeto feito de madeira (acerca da reverência dos politeístas a imagens cultuais: <span class=\"greek\">σέβονται</span> <span class=\"greek\">λίθους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ξύλα</span> Theoph. Ant. 1, 10 [p. 80, 5]).</p><p class=\"entry-text\">ⓐ Acerca de um pedaço de madeira preparado para determinado fim:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Peça relativamente comprida que pode ser fincada no solo, poste (Diod S 5, 18, 4; Maximus Tyr. 2, 8b), como aquela em que Moisés ergueu a serpente de bronze (Num 21:8f) B 12:7.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Clava, porrete (Hdt. 2, 63; 4, 180; Polyb. 6, 37, 3; Herodian 7, 7, 4; PHal 1, 187; PTebt 304, 10; Jos., Bell. 2, 176, Vi. 233), plural (com <span class=\"greek\">μάχαιραι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:47</a>, 55; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:43</a>, 48; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:52</a>.</p><p class=\"entry-text\">ⓑ Dispositivo para prender as extremidades de um prisioneiro, tronco, cepo (Hdt. 6, 75; 9, 37; Lysias 10, 16; Aristoph., Eq. 367; 394; 705; também Chariton 4, 2, 6; OGI 483, 181 [ver a nota]; Job 33:11): <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">ἠσφαλίσατο</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ξύλον</span>, prendeu-lhes os pés ao tronco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:24</a>.</p><p class=\"entry-text\">ⓒ Estrutura de madeira utilizada para crucificação, cruz (Alexis Com. [IV b.c.] 220, 10 <span class=\"greek\">ἀναπήγνυμι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξύλου</span>; Philo, Somn. 2, 213; Just., A II, 3, 1 <span class=\"greek\">ξύλῳ</span> <span class=\"greek\">ἐμπαγῆναι</span>, D. 138, 2 <span class=\"greek\">δι</span>’ <span class=\"greek\">ὕδατος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ξύλου</span>; Iren. 1, 14, 6 [Harv. I 140, 10]; <span class=\"greek\">διὰ</span> <span class=\"greek\">ξύλου</span> <span class=\"greek\">θάνατος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">ξ</span>. <span class=\"greek\">ζωή</span>, <span class=\"greek\">θ</span>. <span class=\"greek\">μὲν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἀδάμ</span>, <span class=\"greek\">ζ</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χριστόν</span> Orig., C. Cels. 6, 36, 28.—Fora do NT, também «forca»: o escoliasta de Aristoph., Ran. 736 cita um provérbio <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">καλοῦ</span> <span class=\"greek\">ξύλου</span> <span class=\"greek\">κἂν</span> <span class=\"greek\">ἀπάγξασθαι</span> = se for preciso enforcar-se, escolha uma árvore decente; Esth 5:14; 6:4, reproduzido por Jos., Ant. 11, 246: um <span class=\"greek\">ξ</span>. de sessenta côvados de altura deve ser cortado. Com maior frequência o AT se refere a pendurar ou empalar o cadáver de um criminoso num poste <span class=\"greek\">ἐπὶ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">ξύλου</span> Gen 40:19; Dt 21:22f; Josh 10:26).—<span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλῳ</span>, o reinado de Jesus está fundado no madeiro (da cruz) B 8:5, cf. versículo 1; 12:1 (de obra profética apócrifa, talvez 4 Esdr 5:5. Ver UHolzmeister, Verb Dom 21, ’41, 69–73). <span class=\"greek\">κρεμάσαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλου</span>, pendurar na cruz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:30</a>; 10:39. <span class=\"greek\">ὁ</span> <span class=\"greek\">κρεμάμενος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:13</a> (Dt 21:23; cf., Mel., P. 70, 507; 104, 805 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλου</span> <span class=\"greek\">κρεμασθείς</span>). <span class=\"greek\">καθελεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξ</span>., descer da cruz (cf. Josh 10:27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:29</a>. <span class=\"greek\">πάσχειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλου</span> B 5:13. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἁμαρτίας</span> <span class=\"greek\">ἀναφέρειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ξ</span>., levar os pecados sobre (ou até) a cruz, a fim de destruí-los nela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:24</a>=Pol 8:1.—WSvLeeuwen, NThSt 24, ’41, 68–81.</p><p class=\"entry-text\">③ Árvore (esse emprego é perceptível em Eur., Hdt.; Ctesias [IV b.c.]: 688 Fgm. 45n p. 500 Jac., em Apollon. Paradox. 17 <span class=\"greek\">παρ</span>’ <span class=\"greek\">Ἰνδοῖς</span> <span class=\"greek\">ξύλον</span> <span class=\"greek\">γίνεσθαι</span>; Theophr., HP 5, 4, 7; Fgm. Iamb. Adesp. 17 Diehl; Plut., Lycurgus 47 [13, 7]; Harpocration s.v. <span class=\"greek\">ὀξυθυμία</span>; PTebt 5, 205 [118 b.c.]; PFlor 152, 4; Gen 1:29; 2:9; 3:1ff; Is 14:8; Eccl 2:5; PsSol 11:5; GrBar 4:8, 16; ApcSed 8:3; Tat. 919, 3 <span class=\"greek\">ξύλῳ</span> <span class=\"greek\">μαντικῷ</span>) Dg 12:8. <span class=\"greek\">ὑγρόν</span>, <span class=\"greek\">ξηρὸν</span> <span class=\"greek\">ξ</span>., árvore verde, árvore seca <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:31</a> (ver <span class=\"greek\">ξηρός</span> 1 e cf. Polyaenus 3, 9, 7 <span class=\"greek\">ξύλα</span> <span class=\"greek\">ξηρά</span> [em oposição a <span class=\"greek\">χλωρά</span>].—AHiggins, ET 57, ’45/46, 292–94). <span class=\"greek\">πάγκαρπον</span> <span class=\"greek\">ξ</span>., árvore que produz todas as espécies de fruto Dg 12:1. <span class=\"greek\">ξ</span>. <span class=\"greek\">ἄκαρπον</span>, árvore sem fruto (comestível), acerca do olmo Hs 2:3. <span class=\"greek\">ξύλῳ</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">συμβάλλειν</span>, comparar-se com uma árvore 1 Cl 23:4a; 2 Cl 11:3 (ambas citações escriturísticas de origem desconhecida). <span class=\"greek\">τὰ</span> <span class=\"greek\">φύλλα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:2</a>b; <span class=\"greek\">καρπὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξ</span>. 1 Cl 23:4b. De árvores ao longo de cursos de água B 11:6 (Ps 1:3). <span class=\"greek\">ξ</span>. <span class=\"greek\">γνώσεως</span> Dg 12:2a (cf. Gen 2:9, 17; ApcMos 7 e outros; Did., Gen. 94, 16); <span class=\"greek\">ξ</span>. (<span class=\"greek\">τῆς</span>) <span class=\"greek\">ζωῆς</span> (Gen 2:9; TestLevi 18:11; ApcEsdr 2:11 p. 26, 5 Tdf.; ApcSed 4:5; ApcMos 19, 22, 28; Did., Gen. 110, 26; <span class=\"greek\">τὰ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ξ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> Theoph. Ant. 2, 24 [p. 156, 19]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:7</a>; 22:2a (RSchran, BZ 24, ’38/39, 191–98), 14, 19; Dg 12:2b (cf. versículo 3 e PsSol 14:3 <span class=\"greek\">ξύλα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span>; ver <span class=\"greek\">ζωή</span> 2b<span class=\"greek\">β</span>; LvSybel, <span class=\"greek\">Ξύλον</span> <span class=\"greek\">ζωῆς</span>: ZNW 19, 1920, 85–91; UHolmberg, D. Baum d. Lebens 1923; HBergema, De Boom des Levens in Scrift en Historie, dissertação, Hilversum, ’38; CHemer, The Letters to the Seven Churches of Asia in Their Local Setting ’89 [’86] 41–47; RAC II 1–34; VIII 112–41).—B. 50; 1385. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξυν-</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξυν</span>-, ver <span class=\"greek\">συν</span>-.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξυράω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ξυράω</span> (<span class=\"greek\">ξύω</span>, «raspar»; Diod S 1, 83, 2; 1, 84, 2; 5, 28, 3; Plut., Mor. 180b; Dio Chrys. 16 [33], 63; Longus 4, 10, 1; Ath. 14, 2; PMich 243, 10 e 11 [I a.d.]), <span class=\"greek\">ξυρέω</span> (autores trágicos, Hdt., Pla. e outros; Lob. acerca de Phryn. p. 205), <span class=\"greek\">ξύρω</span> (Hippocr.; Plut., Mor. 336e <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλὴν</span> <span class=\"greek\">ξυράμενος</span>; Lucian, De Morte Peregr. 17), futuro, 3ª pessoa do singular <span class=\"greek\">ξυρήσει</span> LXX; aoristo, 3ª pessoa do singular <span class=\"greek\">ἐξύρησε</span> LXX. Passivo: futuro <span class=\"greek\">ξυρηθήσομαι</span> LXX; infinitivo aoristo <span class=\"greek\">ξυρηθῆναι</span> Lev 13:34; «raspar, barbear». Em nossa literatura encontram-se as seguintes formas verbais do radical <span class=\"greek\">ξυρ</span>-: médio <span class=\"greek\">ξύρωνται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:24</a> D; futuro <span class=\"greek\">ξυρήσονται</span> 21:24; subjuntivo aoristo <span class=\"greek\">ξυρήσωνται</span>, no mesmo lugar, v.l. Passivo: particípio perfeito <span class=\"greek\">ἐξυρημένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:5</a>. No versículo 6, <span class=\"greek\">ξυρασθαι</span> parece ser caracterizado como forma verbal de <span class=\"greek\">ξυράω</span> por <span class=\"greek\">ἐξυρημένῃ</span> do versículo 5; nesse caso deve ser acentuado como infinitivo presente médio <span class=\"greek\">ξυρᾶσθαι</span> (cf. Diog. L. 7, 166 <span class=\"greek\">ξυρᾶσθαι</span> = fazer-se barbear; Jos., Ant. 19, 294 <span class=\"greek\">ξυρᾶσθαι</span> e Bell. 2, 313 <span class=\"greek\">ξυρήσεσθαι</span>; Philo, Spec. Leg. 1, 5 <span class=\"greek\">ξυρῶνται</span>). Por outro lado, a proximidade imediata de <span class=\"greek\">κείρασθαι</span> torna muito mais provável que seja aoristo, infinitivo aoristo médio de <span class=\"greek\">ξύρω</span>, devendo ser acentuado <span class=\"greek\">ξύρασθαι</span> (outras edições; ver B-D-F §101 p. 47; Mlt-H. 200; 250; Anz 310f).—Médio: fazer-se barbear (ver Schwyzer II 232; B-D-F §317; Rob. 809), <span class=\"greek\">τὴν</span> <span class=\"greek\">κεφαλήν</span>, fazer raspar a própria cabeça (Ps.-Callisth. 1, 3, 2; Num 6:9; Ezk 44:20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:24</a> (ver <span class=\"greek\">εὐχή</span> 2 e Jos., Ant. 19, 294). Sem complemento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:6</a>. Passivo: <span class=\"greek\">ἐξυρημένη</span>, mulher com a cabeça raspada, versículo 5.—DELG s.v. <span class=\"greek\">ξύω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁ, ἡ, τό</h1><div class=\"entry-meta\"><span>artigo definido</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁ</span>, <span class=\"greek\">ἡ</span>, <span class=\"greek\">τό</span>, plural <span class=\"greek\">οἱ</span>, <span class=\"greek\">αἱ</span>, <span class=\"greek\">τά</span>, artigo definido, derivado de pronome demonstrativo, «o, a, os, as». Como o estudo da presença e da omissão do artigo pertence ao domínio da gramática, o dicionário pode limitar-se à apresentação das principais características de seu uso. É difícil estabelecer regras rígidas para o emprego do artigo, pois o estilo de cada autor gozava de particular liberdade nesse ponto.—Kühner-G. I p. 589ff; B-D-F §249–76; Mlt. 80–84; Rob. 754–96; W-S. §17ff; Rdm.2 112–18; Abel §28–32; HKallenberg, RhM 69, 1914, 642ff; FVölker, Syntax d. griech. Papyri I, Der Artikel, Progr. d. Realgymn. Münster 1903; FEakin, AJP 37, 1916, 333ff; CMiller, ibid. 341ff; EColwell, JBL 52, ’33, 12–21 (para uma crítica, ver Mlt-H.-Turner III 183f); ASvensson, D. Gebr. des bestimmten Art. in d. nachklass. Epik ’37; RFink, The Syntax of the Greek Article ’53; JRoberts, Exegetical Helps, The Greek Noun with and without the Article: Restoration Qtly 14, ’71, 28–44; HTeeple, The Greek Article with Personal Names in the Synoptic Gospels: NTS 19, ’73, 302–17; Mussies 186–97.</p><p class=\"entry-text\">① Este, aquele: artigo funcionando como pronome demonstrativo.</p><p class=\"entry-text\">ⓐ Segundo o uso épico (Hes., Works 450: <span class=\"greek\">ἡ</span> = esta [voz]), na citação de Arat., Phaenom. 5: <span class=\"greek\">τοῦ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γένος</span> <span class=\"greek\">ἐσμέν</span>, pois também somos descendência dele (literalmente, «deste») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:28</a>.</p><p class=\"entry-text\">ⓑ <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">δέ</span>, um … o outro (Polyaenus 6, 2, 1 <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">δε</span>; PSI 512, 21 [253 b.c.]); plural <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">δέ</span> (PSI 341, 9 [256 b.c.]; TestJob 29:1), uns … outros, com referência a substantivo anterior: <span class=\"greek\">ἐσχίσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἦσαν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Ἰουδαίοις</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἀποστόλοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:4</a>; 17:32; 28:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:16</a>f. Também sem que essa relação esteja expressa: <span class=\"greek\">τοὺς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἀποστόλους</span>, <span class=\"greek\">τοὺς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">προφήτας</span>, <span class=\"greek\">τοὺς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">εὐαγγελιστάς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:11</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>f, 20f. <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἄλλοι</span> (<span class=\"greek\">δέ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:12</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> … <span class=\"greek\">ἄλλοι</span> <span class=\"greek\">δὲ</span> … <span class=\"greek\">ἕτεροι</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:14</a>. <span class=\"greek\">τινὲς</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">δέ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:18</a> (cf. Pla., Leg. 1, 627a; 2, 658 B.; Aelian, VH 2, 34; Palaeph. 6, 5).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.67\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:67</a>; 28:17, <span class=\"greek\">οἱ</span> <span class=\"greek\">δέ</span> introduz um segundo grupo; pouco antes, em lugar do primeiro grupo, menciona-se a totalidade (cf. X., Hell. 1, 2, 14, Cyr. 3, 2, 12; KMcKay, JSNT 24, ’85, 71f) = mas alguns (como em Arrian, Anab. 5, 2, 7; 5, 14, 4; Lucian, Tim. 4 p. 107; Hesych. Miles. [VI a.d.]: 390 Fgm. 1, 35 final Jac.).</p><p class=\"entry-text\">ⓒ Para indicar o desenvolvimento da narrativa, <span class=\"greek\">ὁ</span> <span class=\"greek\">δέ</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">δέ</span>, mas ele, mas eles (literalmente «este, estes»), são utilizados mesmo sem <span class=\"greek\">ὁ</span> <span class=\"greek\">μέν</span> anterior (igualmente Il. 1, 43; Pla., X.; também Clearchus, Fgm. 76b <span class=\"greek\">τὸν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">εἰπεῖν</span> = mas este homem disse; exemplos de papiros em Mayser II/1, 1926, 57f), por exemplo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:9</a>, 14; 4:4; 9:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:31</a> (cf. Just., A II, 2, 3). <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:18</a>; 28:5. <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">οὖν</span> 1:6; 5:41; 15:3, 30.—JO’Rourke, Paul’s Use of the Art. as a Pronoun, CBQ 34, ’72, 59–65.</p><p class=\"entry-text\">② O, a: função de definir ou delimitar uma entidade, acontecimento ou estado.</p><p class=\"entry-text\">ⓐ Com substantivos.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Com apelativos, ou substantivos comuns, caso em que, como em Pla., Thu., Demosth. e outros, o artigo tem dupla significação: específica ou individualizadora, e genérica.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">א</span> . No emprego individualizador, concentra a atenção numa coisa ou conceito singular, já conhecido ou delimitado de maneira mais definida: coisas e pessoas únicas em sua categoria: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">σελήνη</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανός</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">θάλασσα</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">κτίσις</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> (BWeiss [ver início do verbete <span class=\"greek\">θεός</span>]), <span class=\"greek\">ὁ</span> <span class=\"greek\">διάβολος</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:1</a>, 14), <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">σκοτία</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωή</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">θάνατος</span> etc. (às vezes o artigo é omitido, especialmente com substantivos empregados com preposições; B-D-F §253, 1–4; Rob. 791f; Mlt-Turner 171). <span class=\"greek\">ἐν</span> <span class=\"greek\">συναγωγῇ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:20</a>.—Virtudes, vícios etc. (diversamente do uso inglês): <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀλήθεια</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἁμαρτία</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">δικαιοσύνη</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">σοφία</span> e outros.—O artigo individualizador precede substantivo comum já mencionado anteriormente (sem artigo): <span class=\"greek\">τοὺς</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">ἄρτους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:16</a> (após <span class=\"greek\">πέντε</span> <span class=\"greek\">ἄρτοι</span>, versículo 13). <span class=\"greek\">τὸ</span> <span class=\"greek\">βιβλίον</span> 4:17b (após <span class=\"greek\">βιβλίον</span>, versículo 17a), <span class=\"greek\">τοὺς</span> <span class=\"greek\">μάγους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:7</a> (após <span class=\"greek\">μάγοι</span>, versículo 1). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.43\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:43</a> (40); 12:6 (5); 20:1 (19:41); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:17</a> (11); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:3</a> (2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 15:6</a> (1).—O artigo individualizador também antecede substantivo comum que, em determinada situação, recebe atenção especial como único ou evidente de sua espécie (Hipponax [VI b.c.] 13, 2 West=D.3 16 <span class=\"greek\">ὁ</span> <span class=\"greek\">παῖς</span>, o escravo [que atende]; Diod S 18, 29, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀδελφός</span> = seu irmão; Artem. 4, 71 p. 245, 19 <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνή</span> = tua esposa; ApcEsdr 6:12 p. 31, 17 <span class=\"greek\">μετὰ</span> <span class=\"greek\">Μωσῆ</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὄρει</span> [Sinai]; Demetr. (?): 722 fgm 7 Jac. [em Eus., PE 9, 19, 4] <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> [Moriá]): <span class=\"greek\">τῷ</span> <span class=\"greek\">ὑπηρέτῃ</span>, ao auxiliar (responsável pela sinagoga) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:20</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νιπτῆρα</span>, na bacia (disponível para esse fim) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:5</a>. <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπο</span>, eis este homem (desventurado) 19:5. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παιδίσκης</span> ou <span class=\"greek\">ἐλευθέρας</span>, da escrava (bem conhecida) ou da livre (Agar e Sara) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:22</a>f. <span class=\"greek\">τὸν</span> <span class=\"greek\">σῖτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:38</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιστολῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:9</a> (ver <span class=\"greek\">ἐπιστολή</span>); <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span>, o monte (próximo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:1</a>; 8:1; 14:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:13</a>; 6:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:12</a>; 9:28 e outros; <span class=\"greek\">ἡ</span> <span class=\"greek\">πεισμονή</span>, esta (espécie de) persuasão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:8</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μαρτυρία</span>, o testemunho (requerido) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:36</a>.—O artigo adquire o sentido de <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐξοχήν</span>, «por excelência» (Porphyr., Abst. 24, 7 <span class=\"greek\">ὁ</span> <span class=\"greek\">Αἰγύπτιος</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐρχόμενος</span>, aquele que haveria de vir ou o que vem por excelência = o Messias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:19</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">προφήτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:21</a>, 25; 7:40. <span class=\"greek\">ὁ</span> <span class=\"greek\">διδάσκαλος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰσραήλ</span> 3:10 (Ps.-Clem., Hom. 5, 18 acerca de Sócrates: <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἑλλάδος</span> <span class=\"greek\">διδάσκαλος</span>); cf. MPol 12:2. Com coisas (Stephan. Byz. s.v. <span class=\"greek\">Μάρπησσα</span>: <span class=\"greek\">οἱ</span> <span class=\"greek\">λίθοι</span> = as famosas pedras [do mármore de Paros]): <span class=\"greek\">ἡ</span> <span class=\"greek\">κρίσις</span>, o juízo (final) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:41</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span>, o dia da decisão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:13</a>; (cf. Mi 4:6 Mt); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:25</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">σωτηρία</span>, a (nossa) salvação na consumação dos tempos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:11</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ב</span> . No uso genérico, destaca um indivíduo típico de determinada classe, em vez da classe em si: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀγαθὸς</span> <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:35</a>. <span class=\"greek\">κοινοῖ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span> 15:11. <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐθνικός</span> 18:17. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐργάτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:7</a>. <span class=\"greek\">ἐγίνωσκεν</span> <span class=\"greek\">τί</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀνθρώπῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:25</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">σημεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀποστόλου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:12</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κληρονόμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:1</a>. Assim também em parábolas e alegorias: <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκοδεσπότης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:43</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:11</a>b, 12. O artigo genérico grego muitas vezes é traduzido para o inglês por artigo indefinido ou inteiramente omitido.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. O uso do artigo com nomes próprios varia; em regra geral, a presença do artigo com nome pessoal indica que a pessoa é conhecida; sem artigo, a atenção incide sobre o nome em si (ver Dssm., BPhW 22, 1902, 1467f; BWeiss, D. Gebr. des Art. b. d. Eigennamen [im NT]: StKr 86, 1913, 349–89). Entretanto, percebe-se inequívoca tendência ao emprego do grego moderno, em que todo nome próprio leva artigo (B-D-F §260; Rob. 759–61; Mlt-Turner 165f). A tradição manuscrita varia consideravelmente. Nos evangelhos, o artigo costuma acompanhar <span class=\"greek\">Ἰησοῦς</span>; frequentemente, contudo, falta quando <span class=\"greek\">Ἰ</span>. vem acompanhado de aposto com artigo: <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">Γαλιλαῖος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.69\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:69</a>; <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">Ναζωραῖος</span>, versículo 71; <span class=\"greek\">Ἰ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λεγόμενος</span> <span class=\"greek\">Χριστός</span> 27:17, 22. Semelhantemente, <span class=\"greek\">Μαριὰμ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:14</a>. O artigo às vezes antecede casos oblíquos de nomes próprios indeclináveis, aparentemente para indicar-lhes o caso (B-D-F §260, 2; Rob. 760). Aqui também não existe regra absoluta.—HTeeple, NTS 19, ’73, 302–17 (sinópticos).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. O artigo acompanha costumeiramente nomes de países (B-D-F §261, 4; W-S. § 18, 5 d; Rob. 759f); menos frequentemente, nomes de cidades (B-D-F §261, 1; 2; Rob. 760; Mlt-Turner 170–72). Com <span class=\"greek\">Ἰερουσαλήμ</span>, <span class=\"greek\">Ἱεροσόλυμα</span>, costuma estar ausente (ver <span class=\"greek\">Ἱεροσόλυμα</span>); somente quando esse nome possui modificadores é que precisa do artigo: <span class=\"greek\">ἡ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:25</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἄνω</span> <span class=\"greek\">Ἰ</span>., versículo 26; <span class=\"greek\">ἡ</span> <span class=\"greek\">καινὴ</span> <span class=\"greek\">Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:12</a>. Mesmo nesse caso, porém, falta o artigo quando o modificador segue o nome: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:22</a>.—Nomes de rios levam artigo: <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰορδάνης</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">Εὐφράτης</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">Τίβερις</span> Hv 1, 1, 2 (B-D-F §261, 8; Rob. 760; Mlt-Turner 172). Igualmente nomes de mares: <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀδρίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:27</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. O artigo antecede substantivos acompanhados do genitivo de pronome (<span class=\"greek\">μοῦ</span>, <span class=\"greek\">σοῦ</span>, <span class=\"greek\">ἡμῶν</span>, <span class=\"greek\">ὑμῶν</span>, <span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">ἑαυτοῦ</span>, <span class=\"greek\">αὐτῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:21</a>, 25; 5:45; 6:10–12; 12:49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:27</a>; 10:7; 16:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:19</a>; 6:6 e frequentemente (raramente é omitido: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.72\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:72</a>; 2:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:20</a> e outros).</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. Quando acompanhado dos pronomes possessivos <span class=\"greek\">ἐμός</span>, <span class=\"greek\">σός</span>, <span class=\"greek\">ἡμέτερος</span>, <span class=\"greek\">ὑμέτερος</span>, o substantivo sempre recebe artigo, e o pronome geralmente fica entre artigo e substantivo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:7</a> e frequentemente. Em João, contudo, apenas raramente: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:42</a>; 5:47; 7:16. Ele prefere repetir o artigo quando o possessivo sucede o substantivo: <span class=\"greek\">ἡ</span> <span class=\"greek\">κρίσις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐμή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:30</a>; cf. 7:6; 17:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:3</a> e outros.</p><p class=\"entry-text\"><span class=\"greek\">ζ</span>. Adjetivos (ou particípios), quando modificam substantivos acompanhados de artigo, ou aparecem entre artigo e substantivo: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγαθὴ</span> <span class=\"greek\">μερίς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:42</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">πνεῦμα</span> 12:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:8</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">δικαία</span> <span class=\"greek\">κρίσις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:24</a> e frequentemente, ou aparecem depois do substantivo, com repetição do artigo: <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:7</a>; 9:8; 10:15. <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">αἰώνιος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:2</a>; 2:25. <span class=\"greek\">τὴν</span> <span class=\"greek\">πύλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σιδηρᾶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:10</a>. Apenas raramente um adjetivo sem artigo antecede substantivo com artigo (ver B-D-F §270, 1; Rob. 777; Mlt-Turner 185f): <span class=\"greek\">ἀκατακαλύπτῳ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κεφαλῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:5</a>. <span class=\"greek\">εἶπεν</span> <span class=\"greek\">μεγάλῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φωνῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:10</a> v.l.; cf. 26:24. <span class=\"greek\">κοιναῖς</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">χερσίν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:5</a> D.—Duplo modificador: <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἡτοιμασμένον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">διαβόλῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:41</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">θυσιαστήριον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χρυσοῦν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θρόνου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:3</a>; 9:13. <span class=\"greek\">ἡ</span> <span class=\"greek\">πόρνη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μεγάλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">καθημένη</span> 17:1.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:36</a> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">λαλούμενον</span> é provavelmente leitura errônea (B apresenta <span class=\"greek\">τὸν</span> <span class=\"greek\">λαλ</span>., D <span class=\"greek\">τοῦτον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λ</span>. sem <span class=\"greek\">λαλούμενον</span>).—Sobre o artigo com <span class=\"greek\">ὅλος</span>, <span class=\"greek\">πᾶς</span>, <span class=\"greek\">πολύς</span>, ver os respectivos verbetes.</p><p class=\"entry-text\"><span class=\"greek\">η</span>. Como nos casos do possessivo (<span class=\"greek\">ε</span>) e do adjetivo (<span class=\"greek\">ζ</span>), assim também ocorre com outras expressões que podem modificar um substantivo: <span class=\"greek\">ἡ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐκλογὴν</span> <span class=\"greek\">πρόθεσις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:11</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">διαθήκη</span> 11:27. <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:18</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐντολὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ζωήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:10</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:8</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">διακονία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἁγίους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:4</a>.</p><p class=\"entry-text\"><span class=\"greek\">θ</span>. O artigo antecede o substantivo quando um pronome demonstrativo (<span class=\"greek\">ὅδε</span>, <span class=\"greek\">οὗτος</span>, <span class=\"greek\">ἐκεῖνος</span>), relacionado a ele, vem antes ou depois; por exemplo: <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:24</a>. <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:6</a>. <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:24</a>. <span class=\"greek\">οὗτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τελώνης</span> 18:11 e frequentemente. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">οὗτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.71\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:71</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:25</a>; 23:4, 14, 47. <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">οὗτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:8</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱός</span> <span class=\"greek\">σου</span> <span class=\"greek\">οὗτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:30</a> e frequentemente.—<span class=\"greek\">ἐκείνη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:22</a>; 22:46. <span class=\"greek\">ἐκ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὥρα</span> 10:19; 18:1; 26:55. <span class=\"greek\">ἐκ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">καιρός</span> 11:25; 12:1; 14:1. <span class=\"greek\">ἐκ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πλάνος</span> 27:63 e frequentemente. <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">ἐκείνη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a>, 27. <span class=\"greek\">ἡ</span> <span class=\"greek\">ὥρα</span> <span class=\"greek\">ἐκ</span>. 8:13; 9:22; <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">ἐκ</span>. 9:26, 31; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">ἐκ</span>. 13:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀγρὸς</span> <span class=\"greek\">ἐκ</span>., versículo 44 e frequentemente.—<span class=\"greek\">ὁ</span> <span class=\"greek\">αὐτός</span>, ver <span class=\"greek\">αὐτός</span> 3b.</p><p class=\"entry-text\"><span class=\"greek\">ι</span>. O artigo anteposto a substantivo no nominativo atribui-lhe função vocativa (desde Hom.; ver KBrugman4-AThumb, Griech. Gramm. 1913, 431; Schwyzer II 63f; B-D-F §147; Rob. 769. Sobre a LXX, Johannessohn, Kasus 14f.—ParJer 1:1 <span class=\"greek\">Ἰερεμία</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐκλεκτός</span> <span class=\"greek\">μου</span>; 7:2 <span class=\"greek\">χαῖρε</span> <span class=\"greek\">Βαρούχι</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκονόμος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>): <span class=\"greek\">ναί</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:26</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κοράσιον</span>, <span class=\"greek\">ἔγειρε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:41</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:23</a>; 27:29 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:54</a>; 11:39; 18:11, 13 (Goodsp, Probs. 85–87); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:3</a> e frequentemente.</p><p class=\"entry-text\">ⓑ Adjetivos tornam-se substantivos mediante o acréscimo do artigo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πονηρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:16</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">σοφοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:27</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἅγιοι</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">πλούσιοι</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">πολλοί</span> e outros. Igualmente o neutro: <span class=\"greek\">τὸ</span> <span class=\"greek\">κρυπτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:4</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> 7:6. <span class=\"greek\">τὸ</span> <span class=\"greek\">μέσον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:3</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">θνητόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:4</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀδύνατα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:27</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔλαττον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:7</a>. Também com genitivo subsequente: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀγαθά</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:25</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μωρόν</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀσθενὲς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:25</a>; cf. versículos 27f. <span class=\"greek\">τὸ</span> <span class=\"greek\">γνωστὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:19</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀόρατα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, versículo 20. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀδύνατον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> 8:3. <span class=\"greek\">τὰ</span> <span class=\"greek\">κρυπτὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰσχύνης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:2</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Atributos adjetivais cujo substantivo costuma ser omitido adquirem valor substantivo e, portanto, recebem artigo (B-D-F §241; Rob. 652–54): <span class=\"greek\">ἡ</span> <span class=\"greek\">περίχωρος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:5</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">ξηρά</span> 23:15 (isto é, <span class=\"greek\">γῆ</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀριστερά</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">δεξιά</span> (subentende-se <span class=\"greek\">χείρ</span>) 6:3. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιοῦσα</span> (subentende-se <span class=\"greek\">ἡμέρα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:11</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἔρημος</span> (subentende-se <span class=\"greek\">χώρα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:7</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. O neutro do adjetivo acompanhado de artigo pode adquirir sentido de substantivo abstrato (Thu. 1, 36, 1 <span class=\"greek\">τὸ</span> <span class=\"greek\">δεδιός</span> = temor; Herodian 1, 6, 9; 1, 11, 5 <span class=\"greek\">τὸ</span> <span class=\"greek\">σεμνὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρθένου</span>; M. Ant. 1, 1; Just., D. 27, 2 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σκληροκάρδιον</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀχάριστον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτόν</span>): <span class=\"greek\">τὸ</span> <span class=\"greek\">χρηστὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, a bondade de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:4</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">δυνατόν</span>, poder 9:22. <span class=\"greek\">τὸ</span> <span class=\"greek\">σύμφορον</span>, proveito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.35\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:35</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">γνήσιον</span>, genuinidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:8</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπιεικές</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:5</a> e outros.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. O artigo com numerais indica, como em Il. 5, 271f; X. e outros (HKallenberg, RhM 69, 1914, 662ff), que se menciona parte de um número já conhecido (Diod S 18, 10, 2 <span class=\"greek\">τρεῖς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">φυλὰς</span> … <span class=\"greek\">τὰς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἑπτά</span> = «mas as outras sete»; Plut., Cleom. 804 [8, 4] <span class=\"greek\">οἱ</span> <span class=\"greek\">τέσσαρες</span> = «os outros quatro»; Polyaenus 6, 5 <span class=\"greek\">οἱ</span> <span class=\"greek\">τρεῖς</span> = «os três restantes»; Diog. L. 1, 82 <span class=\"greek\">Βίας</span> <span class=\"greek\">προκεκριμένος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἑπτά</span> = Bias foi considerado superior aos outros dos sete [sábios]. B-D-F §265): <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐννέα</span>, os outros nove <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:17</a>. Cf. 15:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:12</a>f. <span class=\"greek\">οἱ</span> <span class=\"greek\">δέκα</span>, os outros dez (discípulos) 20:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:41</a>; leprosos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:17</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">πέντε</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">εἷς</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">ἄλλος</span>, cinco deles … um … o último <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:10</a>.</p><p class=\"entry-text\">ⓒ O particípio acompanhado de artigo adquire:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. O significado de substantivo: <span class=\"greek\">ὁ</span> <span class=\"greek\">πειράζων</span>, o tentador <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:5</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">βαπτίζων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:14</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">σπείρων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:5</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀλεθρεύων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:28</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀφειλόμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:30</a>, 34. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐλούμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:7</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">λαλούμενον</span>, versículo 9 (Just., D. 32, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">ζητούμενον</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">γινόμενα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:7</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐρχόμενα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:13</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐξουθενημένα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:28</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπάρχοντα</span> (ver <span class=\"greek\">ὑπάρχω</span> 1). Na prática inglesa, muitos desses neutros são traduzidos por oração relativa, como em <span class=\"greek\">β</span> abaixo. B-D-F §413; Rob. 1108f.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. O significado de oração relativa (Ar. 4, 2 e outros, <span class=\"greek\">οἱ</span> <span class=\"greek\">νομίζοντες</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">δεχόμενος</span> <span class=\"greek\">ὑμᾶς</span>, quem vos recebe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:40</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">τύπτοντί</span> <span class=\"greek\">σε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:29</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐμὲ</span> <span class=\"greek\">μισῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:23</a>. <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἕτερον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δεδομένον</span> (<span class=\"greek\">ὸ</span>̔ <span class=\"greek\">δέδοται</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:12</a>. <span class=\"greek\">τινές</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ταράσσοντες</span> <span class=\"greek\">ὑμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:7</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:32</a>; 18:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:7</a>; 2J 7; Jd 4 e outros. Assim especialmente após <span class=\"greek\">πᾶς</span>: <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀργιζόμενος</span>, todo aquele que se ira <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:22</a>. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κρίνων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:1</a> e outros. Depois de <span class=\"greek\">μακάριος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:4</a>, 6, 10. Depois de <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:25</a>.</p><p class=\"entry-text\">ⓓ O infinitivo com artigo neutro (B-D-F §398ff; Rob. 1062–68) é empregado de diversas maneiras.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Equivale a um substantivo (B-D-F §399; Rob. 1062–66): <span class=\"greek\">τὸ</span> (<span class=\"greek\">ἀνίπτοις</span> <span class=\"greek\">χερσὶν</span>) <span class=\"greek\">φαγεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:20</a>. <span class=\"greek\">τὸ</span> (<span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκρῶν</span>) <span class=\"greek\">ἀναστῆναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:10</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀγαπᾶν</span> 12:33; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:8</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ποιῆσαι</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπιτελέσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:11</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">καθίσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:23</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:10</a>.—Frequente com preposições: <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">τοῦ</span>, <span class=\"greek\">διὰ</span> <span class=\"greek\">τό</span>, <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span>, <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span>, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span>, <span class=\"greek\">ἕνεκεν</span> <span class=\"greek\">τοῦ</span>, <span class=\"greek\">ἕως</span> <span class=\"greek\">τοῦ</span>, <span class=\"greek\">μετὰ</span> <span class=\"greek\">τό</span>, <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span>, <span class=\"greek\">πρὸς</span> <span class=\"greek\">τό</span> etc.; ver as respectivas preposições (B-D-F §402–4; Rob. 1068–75).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. O genitivo do infinitivo com artigo, sem preposição, é especialmente frequente (B-D-F §400; Mlt. 216–18; Rob. 1066–68; DEvans, ClQ 15, 1921, 26ff). Esse emprego do infinitivo é particularmente comum em Lk e Paulo, menos frequente em Mt e Mk, bastante raro em outros autores. O genitivo ocorre:</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">א</span> . Em dependência de palavras que regem genitivo: <span class=\"greek\">ἄξιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:4</a> (ver <span class=\"greek\">ἄξιος</span> 1c). <span class=\"greek\">ἐξαπορηθῆναι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ζῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:8</a>. <span class=\"greek\">ἔλαχε</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυμιᾶσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:9</a> (cf. 1 Km 14:47 v.l. <span class=\"greek\">Σαοὺλ</span> <span class=\"greek\">ἔλαχεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βασιλεύειν</span>).</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ב</span> . Em dependência de substantivo (B-D-F §400, 1; Rob. 1066f): <span class=\"greek\">ὁ</span> <span class=\"greek\">χρόνος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τεκεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:57</a>. <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τεκεῖν</span> <span class=\"greek\">αὐτήν</span> 2:6. <span class=\"greek\">ἐξουσία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατεῖν</span> 10:19. <span class=\"greek\">εὐκαιρία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παραδοῦναι</span> 22:6. <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σῴζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:20</a>; <span class=\"greek\">τοῦ</span> <span class=\"greek\">μετέχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:10</a>. <span class=\"greek\">ἐπιποθία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐλθεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:23</a>. <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">διδάσκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:12</a>. <span class=\"greek\">καιρὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἄρξασθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:17</a>. <span class=\"greek\">τ</span>. <span class=\"greek\">ἐνέργειαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δύνασθαι</span>, o poder que o capacita <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:21</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">προθυμία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θέλειν</span>, zelo em desejar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:11</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ג</span> . Às vezes a relação com o substantivo é muito frouxa, e é clara a transição para o sentido consecutivo (= resultado) (B-D-F §400, 2; Rob. 1066f): <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ὀκτὼ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">περιτεμεῖν</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:21</a>. <span class=\"greek\">ὀφειλέται</span> … <span class=\"greek\">τοῦ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ζῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:12</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀκαθαρσίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀτιμάζεσθαι</span> 1:24. <span class=\"greek\">ὀφθαλμοὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βλέπειν</span> 11:8. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔκβασιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δύνασθαι</span> <span class=\"greek\">ὑπενεγκεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:13</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ד</span> . Verbos de impedir ou cessar recebem infinitivo com <span class=\"greek\">τοῦ</span> <span class=\"greek\">μή</span> (ver Schwyzer II 372 acerca do grego anterior; PGen 16, 23 [207 a.d.] <span class=\"greek\">κωλύοντες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σπείρειν</span>; LXX; ParJer 2:5 <span class=\"greek\">φύλαξαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σχίσαι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτιά</span> <span class=\"greek\">σου</span>): <span class=\"greek\">καταπαύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:18</a>. <span class=\"greek\">κατέχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:42</a>. <span class=\"greek\">κρατεῖσθαι</span> 24:16. <span class=\"greek\">κωλύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:47</a>. <span class=\"greek\">παύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:10</a> (Ps 33:14). <span class=\"greek\">ὑποστέλλεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:20</a>, 27. Sem <span class=\"greek\">μή</span>: <span class=\"greek\">ἐγκόπτεσθαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐλθεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:22</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ה</span> . O genitivo do infinitivo aparece após verbos de decidir, exortar, ordenar etc. (1 Ch 19:19; ParJer 7:37 <span class=\"greek\">διδάσκων</span> <span class=\"greek\">αὐτοὺ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀπέχεσθαι</span>): <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">γνώμης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:3</a>. <span class=\"greek\">ἐντέλλεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:10</a> (Ps 90:11). <span class=\"greek\">ἐπιστέλλειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:20</a>. <span class=\"greek\">κατανεύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:7</a>. <span class=\"greek\">κρίνειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:1</a>. <span class=\"greek\">παρακαλεῖν</span> 21:12. <span class=\"greek\">προσεύχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:17</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">στηρίζειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:51</a>. <span class=\"greek\">συντίθεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:20</a>.</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ו</span> . O infinitivo com <span class=\"greek\">τοῦ</span> e <span class=\"greek\">τοῦ</span> <span class=\"greek\">μή</span> apresenta claramente sentido final (= finalidade) (ParJer 5:2 <span class=\"greek\">ἐκάθισεν</span> … <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀναπαῆναι</span> <span class=\"greek\">ὀλίγον</span>; Soph., Lex. I 45f; B-D-F §400, 5, com exemplos de literatura não bíblica e de papiros; Rob. 1067): <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σπείρων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σπείρειν</span>, um semeador saiu para semear <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:3</a>. <span class=\"greek\">ζητεῖν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀπολέσαι</span> = <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἀπολέσῃ</span> 2:13. <span class=\"greek\">τοῦ</span> <span class=\"greek\">δοῦναι</span> <span class=\"greek\">γνῶσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.77\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:77</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κατευθῦναι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span>, versículo 79. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σινιάσαι</span> 22:31. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μηκέτι</span> <span class=\"greek\">δουλεύειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:6</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">αὐτά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:10</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">γνῶναι</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:10</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:13</a>; 11:1; 24:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:24</a>, 27; 8:5; 24:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:2</a>; 20:30; 26:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:7</a> (Ps 39:9); 11:5; GJs 2:3f; 24:1.—O aparentemente solecístico <span class=\"greek\">τοῦ</span> <span class=\"greek\">πολεμῆσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:7</a> apresenta matiz semítico; cf. Hos 9:13 e outros (Mussies 96).—A combinação também pode exprimir:</p><p class=\"entry-text\"><span class=\"hebrew\" lang=\"he\" dir=\"rtl\">ז</span> . Sentido consecutivo (resultado): <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">μετεμελήθητε</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πιστεῦσαι</span> <span class=\"greek\">αὐτῷ</span>, não mudastes de pensamento para crer nele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:32</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">μοιχαλίδα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:3</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">βρέφη</span> <span class=\"greek\">ἔκθετα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:19</a>. Cf. 3:12; 10:25.</p><p class=\"entry-text\">ⓔ O artigo é utilizado com expressões preposicionais (Artem. 4, 33 p. 224, 7 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Περγάμῳ</span>; 4, 36 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Μαγνησίᾳ</span>; 4 [6] Esdr [POxy 1010 recto, 8–12] <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πεδίοις</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὄρεσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μετεώροις</span>; Tat. 31, 2 <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Κράτητα</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">Ἐρατοσθένη</span>): <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Κεγχρεαῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:1</a>. <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐκκλησίαις</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἀσίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:4</a>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀγγέλῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐν</span> (com nome de lugar) <span class=\"greek\">ἐκκλησίας</span> 2:1, 8, 12, 18; 3:1, 7, 14 (acerca dessas passagens, RBorger, TRu 52, ’87, 42–45). <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span>, aos que estão na casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a>. <span class=\"greek\">πάτερ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῖς</span> 6:9. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰταλίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:24</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">Ἰησοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:1</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐριθείας</span> 2:8. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">νόμου</span> 4:14; cf. versículo 16. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">οἰκίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:22</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">εὐωνύμων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:41</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">θυσιαστήριον</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θρόνου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:3</a>; cf. 9:13. Sobre 1:4, ver referência em B-D-F §136, 1 à restituição de Nestle. <span class=\"greek\">οἱ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:21</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:3</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:49</a> e outros.—Neutro: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλοίου</span>, destroços procedentes do navio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:44</a> (diferentemente, FZorell, BZ 9, 1911, 159f). <span class=\"greek\">τὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:19</a>, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:27</a> (Tat. 32, 2 <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">θεοῦ</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινα</span> 2:23. <span class=\"greek\">τὰ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐμέ</span>, minhas circunstâncias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:7</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span>, aquilo que se devia fazer segundo a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:39</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:18</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> 15:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a>; 5:1 (X., Resp. Lac. 13, 11 <span class=\"greek\">ἱερεῖ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span>, <span class=\"greek\">στρατηγῷ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀνθρώπους</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:7</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>, a (criança) em mim GJs 12:2 e outros.</p><p class=\"entry-text\">ⓕ Com advérbio ou expressão adverbial (1 Macc 8:3): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔμπροσθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:4</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔξωθεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:25</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πέραν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:18</a>, 28. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄνω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:1</a>f. <span class=\"greek\">τὰ</span> <span class=\"greek\">κάτω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:23</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὀπίσω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:16</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὧδε</span>, os assuntos daqui <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:9</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πλησίον</span>, o próximo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:43</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">καθεξῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:24</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:5</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μέρους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:10</a>.—Especialmente com indicações temporais: <span class=\"greek\">τό</span>, <span class=\"greek\">τὰ</span> <span class=\"greek\">νῦν</span>, ver <span class=\"greek\">νῦν</span> 2b. <span class=\"greek\">τὸ</span> <span class=\"greek\">πάλιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:2</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">λοιπόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρῶτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:40</a>; 12:16; 19:39. <span class=\"greek\">τὸ</span> <span class=\"greek\">πρότερον</span> 6:62; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:13</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span>, diariamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:3</a>.—<span class=\"greek\">τὸ</span> <span class=\"greek\">πλεῖστον</span>, no máximo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:27</a>.</p><p class=\"entry-text\">ⓖ O artigo com o genitivo subsequente indica parentesco, posse ou dependência: <span class=\"greek\">Ἰάκωβος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ζεβεδαίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:2</a> (Thu. 4, 104 <span class=\"greek\">Θουκυδίδης</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ὀλόρου</span> [subentende-se <span class=\"greek\">υἱός</span>]; Plut., Timol. 3, 2; Appian, Syr. 26 §123 <span class=\"greek\">Σέλευκος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀντιόχου</span>; Jos., Bell. 5, 5; 11). <span class=\"greek\">Μαρία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἰακώβου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:10</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Οὐρίου</span>, a esposa de Urias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:6</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">Χλόης</span>, os de Cloé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:11</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">Ἀριστοβούλου</span>, <span class=\"greek\">οἱ</span> <span class=\"greek\">Ναρκίσσου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:10</a>f. <span class=\"greek\">οἱ</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:33</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:24</a>. <span class=\"greek\">Καισάρεια</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Φιλίππου</span>, Cesareia de Filipe, isto é, cidade de Filipe <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:27</a>.—<span class=\"greek\">τό</span>, <span class=\"greek\">τά</span> <span class=\"greek\">τινος</span>, coisas, assuntos, circunstâncias de alguém (Thu. 4, 83 <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀρριβαίου</span>; Parthenius 1, 6; Appian, Syr. 16 §67 <span class=\"greek\">τὰ</span> <span class=\"greek\">Ῥωμαίων</span>): <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:23</a>; 22:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:33</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:11</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:5</a>; cf. 14:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:33</a>f; 13:11. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:14</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀσθενείας</span> <span class=\"greek\">μου</span> 11:30. <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span>, aquilo que a lei exige <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:14</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">συκῆς</span>, aquilo que aconteceu à figueira <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:21</a>; cf. 8:33. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑαυτῆς</span>, seu próprio proveito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:5</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:4</a>, 21. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παροιμίας</span>, o que diz o provérbio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:22</a> (Pla., Theaet. 183e <span class=\"greek\">τὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ὁμήρου</span>; Menand., Dyscolus 633 <span class=\"greek\">τὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λόγου</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> <span class=\"greek\">μου</span>, na casa de meu Pai (assim Field, Notes 50–56; Goodsp. Probs. 81–83; diferentemente «interesses», PTemple, CBQ 1, ’39, 342–52.—Em contraste com os demais sinópticos, Lucas em outras passagens não apresenta Jesus «em casa») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:49</a> (Lysias 12, 12 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀδελφοῦ</span>; Theocr. 2, 76 <span class=\"greek\">τὰ</span> <span class=\"greek\">Λύκωνος</span>; papiros em Mayser II [1926] p. 8; POxy 523, 3 [II a.d.] convite a um jantar <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Κλαυδίου</span> <span class=\"greek\">Σαραπίωνος</span>; PTebt 316 II, 23 [99 a.d.] <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">Ποτάμωνος</span>; Esth 7:9; Job 18:19; Jos., Ant. 16, 302. Sobre o templo de um deus, Jos., C. Ap. 1, 118 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διός</span>). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:15</a> é classificado aqui por WHatch, ATR 26, ’44, 250–53; ver também <span class=\"greek\">ἐμός</span> b.</p><p class=\"entry-text\">ⓗ O neutro do artigo aparece:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Diante de frases ou orações inteiras (Epict. 4, 1, 45 <span class=\"greek\">τὸ</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">φίλον</span>; Prov. Aesopi 100 P. <span class=\"greek\">τὸ</span> <span class=\"greek\">Οὐκ</span> <span class=\"greek\">οἶδα</span>; Jos., Ant. 10, 205; Just., D. 33, 2 <span class=\"greek\">τὸ</span> <span class=\"greek\">γὰρ</span> … [Ps 109:4]): <span class=\"greek\">τὸ</span> <span class=\"greek\">Οὐ</span> <span class=\"greek\">φονεύσεις</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">μοιχεύσεις</span> <span class=\"greek\">κτλ</span>. (citação do Decálogo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:9</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">Καὶ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">ἀνόμων</span> <span class=\"greek\">ἐλογίσθη</span> (citação de Is 53:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:37</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">Εἰ</span> <span class=\"greek\">δύνῃ</span>, quanto a tuas palavras «Se podes» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:23</a>. Igualmente diante de interrogativas indiretas (Vett. Val. 291, 14 <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">τέτακται</span>; Ael. Aristid. 45, 15 K. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὅστις</span> <span class=\"greek\">ἐστίν</span>; ParJer 6:15 <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">ἀποστείλης</span>; GrBar 8:6 <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">ἐταπεινώθη</span>; Jos., Ant. 20, 28 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πείρᾳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τί</span> <span class=\"greek\">φρονοῖεν</span>; Pel.-Leg. p. 20, 32 <span class=\"greek\">τὸ</span> <span class=\"greek\">τί</span> <span class=\"greek\">γένηται</span>; Mel., Fgm. 8, 2 [Goodsp. p. 311] <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">λούονται</span>): <span class=\"greek\">τὸ</span> <span class=\"greek\">τί</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">θέλοι</span> <span class=\"greek\">καλεῖσθαι</span> <span class=\"greek\">αὐτό</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:62</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">μείζων</span> <span class=\"greek\">αὐτῶν</span> 9:46. <span class=\"greek\">τὸ</span> <span class=\"greek\">πῶς</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">περιπατεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:1</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:48</a>; 22:2, 4, 23f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:21</a>; 22:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:26</a>; Hs 8, 1, 4.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Diante de palavras isoladas extraídas do que precede e assim, por assim dizer, citadas (Epict. 1, 29, 16 <span class=\"greek\">τὸ</span> <span class=\"greek\">Σωκράτης</span>; 3, 23, 24; Hierocles 13 p. 448 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μηδείς</span>): <span class=\"greek\">τὸ</span> ‘<span class=\"greek\">ἀνέβη</span>’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:9</a>. <span class=\"greek\">τὸ</span> ‘<span class=\"greek\">ἔτι</span> <span class=\"greek\">ἅπαξ</span>’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:27</a>. <span class=\"greek\">τὸ</span> ‘<span class=\"greek\">Ἁγάρ</span>’ <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:25</a>.</p><p class=\"entry-text\">ⓘ Outros usos dignos de nota do artigo:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Uso elíptico, no qual parte de uma oração acompanhada de artigo deve ser completada pelo contexto: <span class=\"greek\">ὁ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δύο</span>, o homem com os dois (talentos), isto é, <span class=\"greek\">ὁ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">τάλαντα</span> <span class=\"greek\">λαβών</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:17</a>; cf. versículo 22. <span class=\"greek\">τῷ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">φόρον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:7</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πολύ</span>, <span class=\"greek\">ὀλίγον</span>, o homem que tinha muito, pouco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:15</a>, após Ex 16:18 (cf. Lucian, Bis Accus. 9 <span class=\"greek\">ὁ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σύριγγα</span> [subentende-se <span class=\"greek\">ἔχων</span>]; Arrian, Anab. 7, 8, 3 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θανάτῳ</span> [subentende-se <span class=\"greek\">ὁδόν</span>]).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. <span class=\"greek\">Σαῦλος</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Παῦλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:9</a>; ver <span class=\"greek\">καί</span> 2h.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. O artigo feminino é encontrado em emprego bastante peculiar: <span class=\"greek\">ἡ</span> <span class=\"greek\">οὐαί</span> (<span class=\"greek\">ἡ</span> <span class=\"greek\">θλῖψις</span> ou <span class=\"greek\">ἡ</span> <span class=\"greek\">πληγή</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:12</a>; 11:14. Semelhantemente <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀμήν</span> 3:14 (aqui o artigo masculino evidentemente foi escolhido por causa do nome alternativo de Jesus).</p><p class=\"entry-text\">ⓙ Um só artigo pode referir-se a vários substantivos ligados por <span class=\"greek\">καί</span>:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Quando palavras diversas, singulares ou plurais, são reunidas mediante artigo comum: <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀρχιερεῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γραμματεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:4</a>; cf. 16:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:1</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">προφήταις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ψαλμοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:44</a>. <span class=\"greek\">τῇ</span> <span class=\"greek\">Ἰουδαίᾳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Σαμαρείᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:8</a>; cf. 8:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:17</a> e outros.—Até substantivos de gêneros diferentes podem ser reunidos dessa forma (Aristoph., Eccl. 750; Ps.-Pla., Axioch. 12 p. 37a <span class=\"greek\">οἱ</span> <span class=\"greek\">δύο</span> <span class=\"greek\">θεοί</span>, acerca de Apolo e Ártemis; Ps.-Demetr., Eloc. c. 292; PTebt 14, 10 [114 b.c.]; En 18:14; EpArist 109): <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐντάλματα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διδασκαλίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:22</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:6</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φραγμούς</span> 14:23.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Quando uma mesma pessoa recebe mais de um atributo: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:17</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:3</a>; 11:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:3</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατὴρ</span> (<span class=\"greek\">ἡμῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:3</a>; 3:11, 13. Acerca de Cristo: <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτῆρος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:11</a>; cf. 2:20; 3:18. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μεγάλου</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτῆρος</span> <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:13</a> (PGrenf II, 15 I, 6 [139 b.c.], acerca do rei divinizado Ptolomeu: <span class=\"greek\">τοῦ</span> <span class=\"greek\">μεγάλου</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εὐεργέτου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτῆρος</span> [<span class=\"greek\">ἐπιφανοῦς</span>] <span class=\"greek\">εὐχαρίστου</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Por outro lado, o artigo é repetido quando duas pessoas diferentes são nomeadas: <span class=\"greek\">ὁ</span> <span class=\"greek\">φυτεύων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ποτίζων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:8</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἡγεμών</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:30</a>.</p><p class=\"entry-text\">ⓚ Numa expressão fixa, quando um substantivo no genitivo depende de outro substantivo, o artigo costuma aparecer duas vezes ou não aparecer de modo algum: <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:16</a>; <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:9</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:17</a>; <span class=\"greek\">λόγος</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:13</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>; <span class=\"greek\">ἡμ</span>. <span class=\"greek\">κ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:2</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:20</a>; <span class=\"greek\">υἱ</span>. <span class=\"greek\">ἀ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:6</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀνάστασις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">νεκρῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:31</a>; <span class=\"greek\">ἀ</span>. <span class=\"greek\">ν</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:6</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">κοιλία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μητρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:4</a>; <span class=\"greek\">κ</span>. <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:12</a>.—APerry, JBL 68, ’49, 329–34; MBlack, An Aramaic Approach3, ’67, 93–95.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀβελίσκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino diminutivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀβελίσκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὀβελός</span>, «espeto»; Aristoph., X. e outros; inscrições; PEleph 5, 2; Job 41:22; 4 Macc 11:19; Just., 40, 3 <span class=\"greek\">ὄρθιος</span> <span class=\"greek\">ὀ</span>., «trave vertical» da cruz), diminutivo de <span class=\"greek\">ὀβελός</span>; pequeno espeto ou haste, com <span class=\"greek\">ξίφος</span> ApcPt 15:30.—DELG s.v. <span class=\"greek\">ὀβελός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀγδοήκοντα</h1><div class=\"entry-meta\"><span>numeral cardinal indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀγδοήκοντα</span>, indeclinável (Thu. e outros; inscrições, papiros, LXX; TestJos 16:5; GrBar 4:2; ApcEsdr; ApcSed 12:4; Jos., Bell. 4, 482, Vi. 15; 75), oitenta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:37</a> (IG XII/3, 10, 3 [II b.c.], epitáfio: <span class=\"greek\">θνήσκω</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὀγδώκοντα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἓξ</span> <span class=\"greek\">ἐσιδών</span> = morri depois de ver 86 anos); 16:7; MPol 9:3.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄγδοος, η, ον</h1><div class=\"entry-meta\"><span>numeral ordinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄγδοος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (ver <span class=\"greek\">ὀκτώ</span>; Hom. e posteriores), oitavo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:11</a>; 21:20; MPol 21; Hs 9, 1, 8; 9, 25, 1; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:59</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:8</a> (Gen 21:4; cf. Jos., Ant. 1, 192; Just., D. 24, 1 e outros); 15:9 (Wengst, Didache 200 nota 238), cf. versículo 8. <span class=\"greek\">ὄγδοον</span> <span class=\"greek\">Νῶε</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">κήρυκα</span> <span class=\"greek\">ἐφύλαξεν</span>, preservou Noé como pregador de justiça, juntamente com outros sete (literalmente, «como o oitavo») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:5</a> (sobre essa expressão, cf. Thu. 1, 46, 2; 1, 61, 1; 2, 13, 1; Pla., Leg. 3, 695c <span class=\"greek\">λαβὼν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">ἕβδομος</span>; Plut., Pelop. 284 [13, 7] <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">δωδέκατος</span> <span class=\"greek\">κατελθών</span>; Ps.-Apollod., Epict. 3, 15 <span class=\"greek\">ἡ</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">ἐνάτη</span> = a mãe com oito [filhos]; 2 Macc 5:27 <span class=\"greek\">δέκατος</span> <span class=\"greek\">γενηθείς</span>, «com outros nove»).—DELG s.v. <span class=\"greek\">ὀκτώ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄγκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄγκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e outros; PLond I, 130 [=Neugebauer-Hoesen nº 81], 107; 124f p. 136, termo astrológico «magnitude»; SEG VIII, 802; Philo; Jos., Bell. 4, 319; 7, 443. Empréstimo no rabínico).</p><p class=\"entry-text\">① Matéria de dimensões pesadas, volume: <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> <span class=\"greek\">ὄ</span>., o volume da cabeça, Papias (3:2).</p><p class=\"entry-text\">② Aquilo que impede alguém de fazer algo, peso, fardo, impedimento, extensão figurada de 1: <span class=\"greek\">ὄγκον</span> <span class=\"greek\">ἀποτίθεσθαι</span> <span class=\"greek\">πάντα</span>, deixar de lado todo impedimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a>.—DELG s.v. 2 <span class=\"greek\">ὄγκος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀγκόω</h1><div class=\"entry-meta\"><span>verbo passivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀγκόω</span> (<span class=\"greek\">ὄγκος</span>; ativo em diversos sentidos, autores trágicos e outros; inscrições [por exemplo Kaibel 314, 23]; passivo também em TestSim 4:1; TestLevi 6:9; ApcEsdr 5:13 p. 30, 8 Tdf.), passivo: inchar (devido à gravidez, como em TestLevi 6:9; ApcEsdr 5:13): <span class=\"greek\">ἡ</span> <span class=\"greek\">γαστὴρ</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">ὠγκοῦτο</span> GJs 12:3; <span class=\"greek\">καὶ</span> <span class=\"greek\">εἶδεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Μαρίαν</span> <span class=\"greek\">ὠγκωμένην</span> 15:1; ver também 13:1; 15:2.—DELG s.v. 2 <span class=\"greek\">ὄγκος</span>. M-M s.v. <span class=\"greek\">ὄγκος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅδε, ἥδε, τόδε</h1><div class=\"entry-meta\"><span>pronome demonstrativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅδε</span>, <span class=\"greek\">ἥδε</span>, <span class=\"greek\">τόδε</span> (Hom. e posteriores; inscrições, papiros [ver Rydbeck 88–97, com crítica a Mayser e Bl-D. quanto à alegada raridade em papiros]; LXX [Thackeray p. 191]; En 106:16; TestSol; TestAbr A 8 p. 85, 15 [Stone p. 18]; TestJob, GrBar; ApcMos 22; EpArist 28; Philo; Jos., Ant. 10, 113; apologistas), pronome demonstrativo (Schwyzer II 209f; B-D-F §289; Rob. 696f [sobre a necessária correção das duas últimas obras, ver Rydbeck, citado acima]).</p><p class=\"entry-text\">① Referência a entidade considerada presente ou próxima no contexto da narrativa, este, esta.</p><p class=\"entry-text\">ⓐ Com referência ao que se segue (emprego predominante), especialmente na fórmula <span class=\"greek\">τάδε</span> <span class=\"greek\">λέγει</span>, assim diz …, literalmente «isto é o que … diz» (fórmula introdutória nos decretos dos reis persas: Hdt. 1, 69, 2 e outros; IMagnMai 115, 4 [=SIG 22, ver nota do editor]; Ps.-Pla., Alcib. II, 12, 14c <span class=\"greek\">τ</span>. <span class=\"greek\">λ</span>. <span class=\"greek\">Ἄμμων</span>; Jos., Ant. 11, 26. No AT, frequente na introdução de enunciado profético [Thackeray p. 11]; assim também [segundo a LXX] TestAbr A 8 p. 85, 15 [Stone p. 18]; TestJob 4:3; 7:9; GrBar e ApcMos 22 <span class=\"greek\">τάδε</span> <span class=\"greek\">λέγει</span> <span class=\"greek\">Κύριος</span>. Também em testamentos: PGiss 36, 10 [161 b.c.] <span class=\"greek\">τάδε</span> <span class=\"greek\">λέγει</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">Ἐλληνὶς</span> <span class=\"greek\">Ἀμμωνία</span>; GRudberg, Eranos 11, 1911, 170–79; Mussies 180. Como introdução a carta: Nicol. Dam.: 90 Fgm. 5 p. 336, 22 Jac. Cf. GGerhard, Unters. z. Gesch. d. gr. Briefes: I, D. Anfangsformel, dissertação Heidelberg 1903) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:1</a>, 8, 12, 18; 3:1, 7, 14; B 6:8; 9:2 (Jer 7:3), 5 (Jer 4:3); cf. IPhld 7:2.</p><p class=\"entry-text\">ⓑ Com referência ao que precede (Soph., Hdt. e outros; Aelian, NA 4, 15 p. 85, 28; 9, 63 p. 241, 11; Philostrat., Vi. Apoll. 218, 25; 271, 3 e outros; Jos., Ant. 17, 2; 19; Just., A II, 5, 3): <span class=\"greek\">γυνή</span> <span class=\"greek\">τις</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">τῇδε</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἀδελφή</span>, certa mulher … e esta tinha uma irmã <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:39</a> (cf. Gen 25:24; 38:27; Judg 11:37 B; MJohannessohn, ZVS 66, ’39, p. 184, 7); 16:25 v.l. (Marcião; ver Zahn, Gesch. des ntl. Kanons II/2, 1892, 480) <span class=\"greek\">ἥδε</span> <span class=\"greek\">ἀπεκρίθη</span> 1 Cl 12:4.</p><p class=\"entry-text\">ⓒ Com referência ao tempo como contexto presente (Just., A I, 45, 6, A II, 12, 6): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἀδὰμ</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">τῆσδε</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμέρας</span>, desde Adão até o presente 1 Cl 50:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇδε</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιστολῇ</span>, nesta carta (que estou escrevendo) 63:2.</p><p class=\"entry-text\">② Referência a entidade não especificada, tal e tal: <span class=\"greek\">εἰς</span> <span class=\"greek\">τήνδε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>, para esta ou aquela cidade, para determinada cidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:13</a> (Eur., Orestes 508 e outros; <span class=\"greek\">τήνδε</span> em lugar do ático <span class=\"greek\">τὴν</span> <span class=\"greek\">δεῖνα</span> ou <span class=\"greek\">τὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τήν</span> Epict. 1, 12, 28 [as duas formas lado a lado]; não é expressão estritamente vernácula, contrariamente a MDibelius/HGreeven, Hermeneia Comm. ’76 ad loc; ver Rydbeck 96f. Cf. Cyr. Scyth. p. 207, 20 <span class=\"greek\">τῆσδε</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>; 185, 13; Plut., Mor. 623e <span class=\"greek\">τήνδε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span> [W-S. §23, 1c nota 2; B-D-F §289; Rob. 696f.—A mesma expressão em Appian, Liby. 108 §510 e Ael. Aristid. 46 p. 384 D.]; <span class=\"greek\">τόνδε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄνθρωπον</span> [Hierocles 11, 439]; <span class=\"greek\">τόδε</span>, «isto e aquilo» [B-D-F loc. cit.; também Plut., Mor. 168d; SIG2 737, 62]; <span class=\"greek\">τοῦδέ</span> <span class=\"greek\">τινος</span> = <span class=\"greek\">τοῦ</span> <span class=\"greek\">δεῖνος</span> [PMich 154, 24—c. 300 a.d.]; cf. o uso no grego moderno de <span class=\"greek\">ὁ</span> <span class=\"greek\">τάδε</span>(<span class=\"greek\">ς</span>) = <span class=\"greek\">ὁ</span> <span class=\"greek\">δεῖνα</span> [KBrugmann, Die Demonstrativpronomina: ASG[Leipz] 22, 1904, 133 nota]; JWackernagel, Syntax I2 1928, 108). <span class=\"greek\">ὅδε</span> aparece também como v.l. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:23</a>.—Rydbeck, 88–99.—DELG. M-M, mas ver Rydbeck.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁδεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁδεύω</span> (<span class=\"greek\">ὁδός</span>), 1º aoristo, 3ª pessoa do singular <span class=\"greek\">ὥδευσε</span> (TestJob 52:10); infinitivo <span class=\"greek\">ὁδεῦσαι</span> (Hom. e outros; OGI 199, 28; POxy 1537, 18; 22; 1771, 10; LXX, Philo, Joseph.; SibOr 3, 367), ir, viajar, fazer viagem, com implicação de utilizar caminho estabelecido: <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ὁδεύειν</span>, seguir seu caminho 19:1 (Artem. 2, 12; 37; cf. Philo, Poster. Cai. 155 <span class=\"greek\">ἀτραπὸν</span> <span class=\"greek\">ὁδ</span>). <span class=\"greek\">δι</span>’ <span class=\"greek\">ἧς</span> (isto é, <span class=\"greek\">ἀνοδίας</span>.—<span class=\"greek\">ὁδ</span>. <span class=\"greek\">διά</span> como em X., An. 7, 8, 8; Jos., Ant. 20, 118) <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐδύνατο</span> <span class=\"greek\">ὁδεῦσαι</span>, pela qual alguém não conseguia andar, isto é, onde não havia caminho ou estrada Hv 1, 1, 3. Sem complemento (Tob 6:6 BA; Jos., Bell. 1, 264; 3, 115): <span class=\"greek\">Σαμαρίτης</span> <span class=\"greek\">ὁδεύων</span>, um samaritano que estava viajando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:33</a> (ASouter, Exp. 8ª série, 8, 1914, 94). Passivo (Strabo 5, 1, 7): <span class=\"greek\">ῥᾳδίως</span> (latim raro) <span class=\"greek\">ὁδεύεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span>, o lugar é facilmente alcançado Hv 4, 1, 2.—New Docs 4, 146. DELG s.v. <span class=\"greek\">ὁδός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁδηγέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁδηγέω</span> (<span class=\"greek\">ὁδηγός</span>), futuro <span class=\"greek\">ὁδηγήσω</span>; 1º aoristo <span class=\"greek\">ὡδήγησα</span> LXX; passivo, aoristo, 3ª pessoa do singular <span class=\"greek\">ὡδηγήθη</span> (Just.) ([sobre <span class=\"greek\">ὁδαγέω</span>, ver B-D-F §29, 3] Aeschyl. e outros; inscrições da Transjordânia [NGG Phil.-Hist. Kl. Fachgr. V n.s. I/1, ’36 p. 3, 1: condução divina]; Kaibel 1041, 1; PSI 332, 6; LXX; Test12Patr, Just.; Tat. 13, 2).</p><p class=\"entry-text\">① Auxiliar alguém a alcançar destino desejado, conduzir, guiar, literalmente (Jos., Vi. 96; <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">Μωσῆς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">Ἰουδαίους</span> Theoph. Ant. 3, 20 [p. 242, 16]), com <span class=\"greek\">τινά</span>, alguém: <span class=\"greek\">τυφλὸς</span> <span class=\"greek\">τυφλόν</span> (cf. Hesiod, Astron. Fgm. 182 Rz., um cego; Plut., Mor. 139a <span class=\"greek\">τυφλούς</span>; TestReub 2:9; Ps.-Phoc. 24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:39</a>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, conduzir alguém a alguma coisa (cf. M. Ant. 7, 55, 1 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τί</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">φύσις</span> <span class=\"greek\">ὁδηγεῖ</span>; PSI loc. cit.; Ps 106:30; 22:3; 24:5): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">πηγὰς</span> <span class=\"greek\">ὑδάτων</span>, às fontes das águas da vida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:17</a>.</p><p class=\"entry-text\">② Auxiliar alguém a adquirir informações ou conhecimento, conduzir, guiar, orientar, extensão figurada de 1 (Plut., Mor. 954b; Sextus 167 <span class=\"greek\">σοφία</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">ὁδηγεῖ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεόν</span>; LXX; Theoph. Ant. 1, 14 [p 90, 12]): acerca do Espírito, <span class=\"greek\">ὁδηγήσει</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">πᾶσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:13</a> (na literatura hermética, Hermes-Nous conduz as almas ao conhecimento: Herm. Wr. 10, 21 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐσεβῆ</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">νοῦς</span> <span class=\"greek\">ὁδηγεῖ</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γνώσεως</span> <span class=\"greek\">φῶς</span>. Cf. 4, 11; 7, 2; 9, 10; 12, 12. Rtzst., Poim. 23, 5, Mysterienrel3 297; PGM 13, 523ff <span class=\"greek\">πάντα</span> <span class=\"greek\">κινήσεις</span> … <span class=\"greek\">Ἑρμοῦ</span> <span class=\"greek\">σε</span> <span class=\"greek\">ὁδηγοῦντος</span>.—Wsd 9:11; 10:10, 17; TestJud 14:1 <span class=\"greek\">εἰς</span> <span class=\"greek\">πλάνην</span>. Theoph. Ant. 3, 15 [p. 234, 118] <span class=\"greek\">λόγος</span> <span class=\"greek\">ἅγιος</span> <span class=\"greek\">ὁ</span>.). Sobre a mentira: <span class=\"greek\">ὁδηγεῖ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κλοπήν</span>, conduz ao roubo D 3:5. Sobre a queixa: <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βλασφημίαν</span> 3:6. Sobre a adivinhação: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εἰδωλολατρείαν</span> 3:4 (cf. TestJud 19:1 <span class=\"greek\">ἡ</span> <span class=\"greek\">φιλαργυρία</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">εἰδωλολατρείαν</span> <span class=\"greek\">ὁδηγεῖ</span>). Também <span class=\"greek\">ὁδ</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span> (TestGad 5:7) 3:2f. Sem qualificação adicional: <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μή</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὁδηγήσει</span> <span class=\"greek\">με</span>, se ninguém me orientar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:31</a>.—DELG s.v. <span class=\"greek\">ὁδός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁδηγός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁδηγός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὁδός</span>, <span class=\"greek\">ἡγέομαι</span>; sobre <span class=\"greek\">ὁδαγός</span> [códice D e ApcrEzek P2, recto 7], ver B-D-F §29, 3).</p><p class=\"entry-text\">① Alguém que conduz pelo caminho até um destino desejado, guia, condutor (Polyb. 5, 5, 15; Plut., Alex. 680 [27, 3]; PCairZen 770, 14 [III b.c.]; Jos., Ant. 12, 305; 1 Macc 4:2; 2 Macc 5:15; cf. Philo, Mos. 1, 178): acerca de Judas como guia dos homens que prenderam Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:16</a>.</p><p class=\"entry-text\">② Alguém que ajuda outra pessoa a seguir um caminho, guia, orientador, em linguagem figurada (Wsd 7:15; 18:3; Jos., Ant. 1, 217): <span class=\"greek\">ὁδηγὸς</span> <span class=\"greek\">τυφλῶν</span>, guia de cegos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:19</a>. <span class=\"greek\">τυφλοί</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">ὁδηγοὶ</span> <span class=\"greek\">τυφλῶν</span>, são guias cegos de cegos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:14</a>. <span class=\"greek\">ὁδηγοὶ</span> <span class=\"greek\">τυφλοί</span> (Paroem. Gr.: Apostol. 11, 50) 23:16, 24.—DELG s.v. <span class=\"greek\">ὁδός</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀδμή</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀδμή</span>, ver <span class=\"greek\">ὀσμή</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁδοιπορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁδοιπορέω</span> (<span class=\"greek\">ὁδοιπόρος</span>, «viajante», de <span class=\"greek\">ὁδός</span> + <span class=\"greek\">πόρος</span>, «passagem»; Soph., Hdt. e outros; Jos., Vi. 157, Ant. 14, 226; SIG 885, 28; PLond I, 121, 181 p. 90 [III a.d.]=PGM 7, 181; Cat. Cod. Astr. 113, 31 <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὁδοιποροῦσι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀποπλέουσιν</span>), viajar, estar a caminho: <span class=\"greek\">ὁδοιπορούντων</span> <span class=\"greek\">ἐκείνων</span>, enquanto estavam a caminho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:9</a>.—DELG s.v. <span class=\"greek\">ὁδός</span> e <span class=\"greek\">πόρος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁδοιπορία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁδοιπορία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (ver o verbete precedente; Hom. Hymns, Hdt. e outros; Diod S 5, 29, 1; Epict. 3, 10, 11; POxy 118 verso, 6; Wsd 13:18; 18:3; 1 Macc 6:41; TestAbr; Philo, Mut. Nom. 165, Leg. ad Gai. 254; Jos., Ant. 5, 53), caminhada, viagem: <span class=\"greek\">κεκοπιακὼς</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>., cansado da viagem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:6</a> (TestAbr B 2 p. 107, 1 [Stone p. 62] <span class=\"greek\">ἐκοπιάθη</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδ</span>.; Jos., Ant. 2, 321 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοιπορίας</span> <span class=\"greek\">κεκοπωμένος</span>; 3, 3; 2, 257; Dio Chrys. 77 [27], 1 <span class=\"greek\">οἱ</span> <span class=\"greek\">διψῶντες</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὁδοιπόρων</span>). Plural (Hdt. 8, 118; X., Oec. 20, 18): viagens <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:26</a>.—DELG s.v. <span class=\"greek\">ὁδός</span> e <span class=\"greek\">πόρος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0249-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁδοποιέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁδοποιέω</span> (<span class=\"greek\">ὁδός</span>, <span class=\"greek\">ποιέω</span>), 1º aoristo <span class=\"greek\">ὡδοποίησα</span> LXX (X., An. 3, 2, 24; 4, 8, 8; 5, 1, 13; Appian, Liby. 91 §430, Bell. Civ. 1, 78 §356 e outros; Arrian, Anab. 1, 26, 1; Herodian 3, 3, 7; OGI 175, 10 [II b.c.]; Is 62:10; Ps 79:10; Just., D. 131, 3 <span class=\"greek\">ὁδοποιηθεῖσαν</span> <span class=\"greek\">θάλασσαν</span>; Ath., R. 11 p. 60, 1), fazer um caminho ou passagem, acerca dos discípulos: <span class=\"greek\">ἤρξαντο</span> <span class=\"greek\">ὁδοποιεῖν</span> <span class=\"greek\">τίλλοντες</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">στάχυας</span>, começaram a abrir caminho ao colher as espigas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:23</a> v.l.—DELG s.v. <span class=\"greek\">ὁδός</span>. M-M.</p></section></article>\n"};
